import { test } from 'node:test';
import assert from 'node:assert/strict';
import { encontrarPorId, posicaoPorId } from './solution.mjs';

test('encontra o objeto com o id pedido', () => {
  const lista = [{ id: 1, nome: 'Ana' }, { id: 2, nome: 'Beto' }];
  assert.deepEqual(encontrarPorId(lista, 2), { id: 2, nome: 'Beto' });
});

test('não encontrou: find devolve undefined e findIndex devolve -1', () => {
  assert.equal(encontrarPorId([{ id: 1 }], 99), undefined);
  assert.equal(posicaoPorId([{ id: 1 }], 99), -1);
});

test('lista vazia devolve undefined', () => {
  assert.equal(encontrarPorId([], 1), undefined);
});

test('recusa valor que não é lista', () => {
  assert.throws(() => encontrarPorId('abc', 1));
});

solutionCode:
export function encontrarPorId(lista, id) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.find((item) => item.id === id);
}

export function posicaoPorId(lista, id) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.findIndex((item) => item.id === id);
}
